isPublic = (ip) => ip !~ /^10\./ and ip !~ /^192\.168\./ and ip !~ /^172\.(1[6-9]|2[0-9]|3[01])\./ and ip !~ /^169\.254\./ and ip !~ /^127\./ and ip !~ /^(22[4-9]|23[0-9])\./ and ip !~ /^255\./ and ip != "0.0.0.0" and not strings.containsStr(v: ip, substr: ":")

from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "network_flow" and r._field == "bytes_up")
  |> filter(fn: (r) => r.src_ip =~ cidrRe or r.dst_ip =~ cidrRe)
  |> filter(fn: (r) => isPublic(ip: r.dst_ip))
  |> group(columns: ["src_ip", "dst_ip"])
  |> sum()
  |> group()
  |> sort(columns: ["_value"], desc: true)
  |> limit(n: 25)
  |> keep(columns: ["src_ip", "dst_ip", "_value"])

